using System;
using System.IO;
using UnityEditor;
using UnityEngine;
namespace Workbench.Editor {
public static class CriticalChecks {
 public static void CheckImportedArt(){var art=AssetDatabase.LoadAssetAtPath<ArtCatalog>("Assets/Workbench/Generated/ArtCatalog.asset");foreach(var e in art.entries){if(!e.sprite)throw new Exception("Missing sprite: "+e.key);var importer=(TextureImporter)AssetImporter.GetAtPath(AssetDatabase.GetAssetPath(e.sprite));var settings=new TextureImporterSettings();importer.ReadTextureSettings(settings);if(importer.filterMode!=FilterMode.Point||importer.mipmapEnabled||importer.spritePixelsPerUnit!=64||importer.textureCompression!=TextureImporterCompression.Uncompressed||settings.spriteMeshType!=SpriteMeshType.FullRect)throw new Exception("Incorrect pixel import: "+e.key);}foreach(var clip in GameData.Load().clips)foreach(var frame in clip.frames)if(!art.Get(frame))throw new Exception("Missing animation frame: "+frame);foreach(string key in new[]{"cream_panel","wood_panel","dark_panel","orange_button_normal","cream_button_normal","inventory_slot_normal"})if(art.Get("UI/NineSlice/"+key).border==Vector4.zero)throw new Exception("Missing nine-slice borders: "+key);File.WriteAllText("TestResults/art-import.txt","PASS: "+art.entries.Length+" sprites Point/64 PPU/FullRect/uncompressed/no mipmaps; all animation frames resolve; nine-slice borders imported.\n");}
 [MenuItem("Workbench/Run critical checks")]
 public static void Run(){Directory.CreateDirectory("TestResults");try{var passed=RuleChecks.Run(GameData.Load());var save=new SaveSystem(Path.GetFullPath("TestResults/SaveRoundtrip"));save.Data.levels[9].stars[4]=true;save.Data.settings.effects=.3f;save.Data.levels[9].build=new[]{new Placement{id=8,type=0,x=2,y=2}};if(!save.Write())throw new Exception("Save write");var reloaded=new SaveSystem(Path.GetFullPath("TestResults/SaveRoundtrip"));if(!reloaded.Data.levels[9].stars[4]||reloaded.Data.levels[9].build[0].id!=8||reloaded.Data.settings.effects!=.3f)throw new Exception("Save roundtrip");passed.Add("Save/load stars, assembly and settings roundtrip");
var oldSave=Path.GetFullPath("TestResults/SaveMigration/Old/workbench-save.json");var newSave=Path.GetFullPath("TestResults/SaveMigration/New/workbench-save.json");Directory.CreateDirectory(Path.GetDirectoryName(oldSave));Directory.CreateDirectory(Path.GetDirectoryName(newSave));File.WriteAllText(oldSave,JsonUtility.ToJson(save.Data));if(File.Exists(newSave))File.Delete(newSave);if(!SaveSystem.Migrate(oldSave,newSave))throw new Exception("Migration did not copy");var migrated=new SaveSystem(Path.GetDirectoryName(newSave));if(!migrated.Data.levels[9].stars[4]||migrated.Data.levels[9].build[0].id!=8||!File.Exists(oldSave))throw new Exception("Migration lost progress or source");File.WriteAllText(oldSave,"invalid");if(SaveSystem.Migrate(oldSave,newSave)||!new SaveSystem(Path.GetDirectoryName(newSave)).Data.levels[9].stars[4])throw new Exception("Migration overwrote current save");passed.Add("Rename migrates progress once and preserves old/current saves");var cameras=CameraDevices.Enumerate();if(!string.IsNullOrEmpty(CameraDevices.LastError))throw new Exception(CameraDevices.LastError);File.WriteAllText("TestResults/camera-enumeration.txt",string.Join("\n",Array.ConvertAll(cameras,c=>c.index+": "+c.name)));passed.Add("Native Windows camera enumeration reads real names without opening devices");
passed.Add(ProgressResetChecks.Run());File.WriteAllText("TestResults/critical-tests.txt",string.Join("\n",passed.ConvertAll(s=>"PASS "+s)));Debug.Log("Passed "+passed.Count+" critical checks");}catch(Exception e){File.WriteAllText("TestResults/critical-tests.txt","FAIL "+e);throw;}}
}
}
